public class Solution {
    public double Average(int[] salary) {
        long sum = 0;
        int mn = int.MaxValue, mx = int.MinValue;
        foreach (int s in salary) {
            sum += s;
            if (s < mn) mn = s;
            if (s > mx) mx = s;
        }
        return (double)(sum - mn - mx) / (salary.Length - 2);
    }
}
