```csharp
public class Solution {
    public int CountTriples(int n) {
        int count = 0;
        for (int a = 1; a <= n; a++) {
            for (int b = 1; b <= n; b++) {
                int s = a * a + b * b;
                int c = (int)System.Math.Sqrt(s);
                while (c * c < s) c++;
                while (c * c > s) c--;
                if (c * c == s && c <= n) count++;
            }
        }
        return count;
    }
}
