public class Solution {
    public string Evaluate(string s, IList<IList<string>> knowledge) {
        var map = new Dictionary<string, string>();
        foreach (var kv in knowledge) map[kv[0]] = kv[1];
        var sb = new System.Text.StringBuilder();
        int i = 0, n = s.Length;
        while (i < n) {
            if (s[i] == '(') {
                int j = s.IndexOf(')', i + 1);
                string key = s.Substring(i + 1, j - i - 1);
                if (map.TryGetValue(key, out var v)) sb.Append(v);
                else sb.Append('?');
                i = j + 1;
            } else {
                sb.Append(s[i]);
                i++;
            }
        }
        return sb.ToString();
    }
}
