Reverse the edges and run Kahn's topological sort, starting from the terminal nodes.

1. Build the reverse graph: for each edge `i -> j`, record `j -> i`.
2. Let `outdeg[i]` be the number of outgoing edges of node `i`.
3. Push every node with `outdeg = 0` (the terminal nodes) onto a queue. These are safe.
4. Pop a safe node `v`. For each predecessor `u` of `v` in the reverse graph, decrement `outdeg[u]`. When it reaches 0, all of `u`'s outgoing edges lead to safe nodes, so `u` is safe; push it.
5. Nodes on a cycle, or with a path to a cycle, never reach `outdeg = 0`, so they are never marked safe.
6. Collect the safe nodes by scanning indices `0..n-1`, which gives ascending order.

This runs in O(n + E) time.

```csharp
public class Solution {
    public IList<int> EventualSafeNodes(int[][] graph) {
        int n = graph.Length;
        var rev = new List<int>[n];
        for (int i = 0; i < n; i++) rev[i] = new List<int>();
        int[] outdeg = new int[n];
        for (int i = 0; i < n; i++) {
            outdeg[i] = graph[i].Length;
            foreach (int j in graph[i]) rev[j].Add(i);
        }
        var q = new Queue<int>();
        bool[] safe = new bool[n];
        for (int i = 0; i < n; i++) if (outdeg[i] == 0) q.Enqueue(i);
        while (q.Count > 0) {
            int v = q.Dequeue();
            safe[v] = true;
            foreach (int u in rev[v]) {
                if (--outdeg[u] == 0) q.Enqueue(u);
            }
        }
        var res = new List<int>();
        for (int i = 0; i < n; i++) if (safe[i]) res.Add(i);
        return res;
    }
}
```

