Use breadth-first search (BFS), going level by level from the root. BFS avoids the deep recursion that a degenerate tree with up to 10^5 nodes would cause. The first leaf reached is the nearest one, so its level is the answer.

- If the tree is empty, return 0.
- Otherwise, process the queue one level at a time, increasing the depth counter for each level.
- Return the depth as soon as a node with no children is found.

```csharp
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public int val;
 *     public TreeNode left;
 *     public TreeNode right;
 *     public TreeNode(int val=0, TreeNode left=null, TreeNode right=null) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
public class Solution {
    public int MinDepth(TreeNode root) {
        if (root == null) return 0;
        var q = new System.Collections.Generic.Queue<TreeNode>();
        q.Enqueue(root);
        int depth = 0;
        while (q.Count > 0) {
            depth++;
            int n = q.Count;
            for (int i = 0; i < n; i++) {
                var node = q.Dequeue();
                if (node.left == null && node.right == null) return depth;
                if (node.left != null) q.Enqueue(node.left);
                if (node.right != null) q.Enqueue(node.right);
            }
        }
        return depth;
    }
}
```

