inference_trace:
Build a trie from the reversed words, and keep the stream in a buffer. On each query, walk the trie from the newest character backwards. Return true as soon as the walk reaches the end of a word. Stop if the trie path breaks or the walk exceeds the maximum word length (200).

To keep memory bounded, the buffer is a circular buffer of size equal to the maximum word length.

Cost: building the trie is O(total word length). Each query is O(max word length), so at most 4·10⁴ × 200 = 8·10⁶ steps overall.

```csharp
public class StreamChecker {
    private int[,] next;
    private bool[] end;
    private int count;
    private char[] buf;
    private int maxLen;
    private int pos;
    private int size;

    public StreamChecker(string[] words) {
        int total = 1;
        maxLen = 0;
        foreach (var w in words) { total += w.Length; if (w.Length > maxLen) maxLen = w.Length; }
        next = new int[total, 26];
        end = new bool[total];
        count = 1;
        foreach (var w in words) {
            int node = 0;
            for (int i = w.Length - 1; i >= 0; i--) {
                int c = w[i] - 'a';
                if (next[node, c] == 0) next[node, c] = count++;
                node = next[node, c];
            }
            end[node] = true;
        }
        buf = new char[maxLen];
        pos = 0;
        size = 0;
    }

    public bool Query(char letter) {
        buf[pos] = letter;
        pos = (pos + 1) % maxLen;
        if (size < maxLen) size++;
        int node = 0;
        int idx = pos;
        for (int k = 0; k < size; k++) {
            idx = (idx - 1 + maxLen) % maxLen;
            int c = buf[idx] - 'a';
            node = next[node, c];
            if (node == 0) return false;
            if (end[node]) return true;
        }
        return false;
    }
}
```

