Approach:

1. For each row, count the soldiers with a binary search. Because all 1's come before all 0's, the count equals the index of the first 0 in that row.
2. Build the list of row indices and sort it by soldier count. When counts are equal, sort by row index, which matches the tie-breaking rule.
3. Return the first `k` indices from the sorted list.

```csharp
public class Solution {
    public int[] KWeakestRows(int[][] mat, int k) {
        int m = mat.Length;
        int[] cnt = new int[m];
        for (int i = 0; i < m; i++) {
            int lo = 0, hi = mat[i].Length;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (mat[i][mid] == 1) lo = mid + 1; else hi = mid;
            }
            cnt[i] = lo;
        }
        var idx = new System.Collections.Generic.List<int>();
        for (int i = 0; i < m; i++) idx.Add(i);
        idx.Sort((a, b) => cnt[a] != cnt[b] ? cnt[a].CompareTo(cnt[b]) : a.CompareTo(b));
        int[] res = new int[k];
        for (int i = 0; i < k; i++) res[i] = idx[i];
        return res;
    }
}
```

