A word is uncommon exactly when it appears once across both sentences combined. So I count how often each word occurs over both sentences and return the words whose total count is 1.

```csharp
using System.Collections.Generic;

public class Solution {
    public string[] UncommonFromSentences(string s1, string s2) {
        var count = new Dictionary<string, int>();
        foreach (var w in (s1 + " " + s2).Split(' ', System.StringSplitOptions.RemoveEmptyEntries)) {
            count.TryGetValue(w, out int c);
            count[w] = c + 1;
        }
        var res = new List<string>();
        foreach (var kv in count) if (kv.Value == 1) res.Add(kv.Key);
        return res.ToArray();
    }
}
```

